namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Name { get; set; }
    public string? Description { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string CourseCode { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public int DepartmentId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20, ErrorMessage = "Student ID cannot exceed 20 characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and linguistics." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Fundamental laws of nature, mechanics, and thermodynamics." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "World history, civilizations, and historiography." },
        ];

        _courses =
        [
            // Computer Science
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen earned her PhD from MIT and has over 15 years of teaching experience in introductory computer science. Her research focuses on CS education and making programming accessible to all students.", DepartmentId = 1, IsFeatured = true },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures (linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. Brian Okafor", InstructorBio = "Dr. Okafor is an associate professor specializing in algorithm optimization. He previously worked at Google Research before joining academia.", DepartmentId = 1 },
            new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and an introduction to NoSQL systems. Includes a semester-long project building a complete database application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Sara Patel", InstructorBio = "Dr. Patel has worked in industry at Oracle and Amazon before transitioning to teaching. She brings real-world experience to her courses on data management.", DepartmentId = 1 },
            new() { Id = 4, CourseCode = "CS 450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, SVMs, decision trees, and practical applications using scikit-learn and TensorFlow.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen earned her PhD from MIT and has over 15 years of teaching experience in introductory computer science. Her research focuses on CS education and making programming accessible to all students.", DepartmentId = 1, IsFeatured = true },

            // Mathematics
            new() { Id = 5, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is an award-winning educator who has published extensively on effective pedagogy for introductory mathematics courses.", DepartmentId = 2, IsFeatured = true },
            new() { Id = 6, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, determinants, eigenvalues, and linear transformations. Applications in computer graphics and data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Prof. Elena Ruiz", InstructorBio = "Prof. Ruiz specializes in applied linear algebra and has consulted for several aerospace companies on computational methods.", DepartmentId = 2 },
            new() { Id = 7, CourseCode = "MATH 330", Title = "Probability & Statistics", Description = "Probability theory, distributions, hypothesis testing, regression analysis, and Bayesian methods.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is an award-winning educator who has published extensively on effective pedagogy for introductory mathematics courses.", DepartmentId = 2 },

            // English
            new() { Id = 8, CourseCode = "ENG 110", Title = "Academic Writing", Description = "Fundamentals of college-level writing: thesis development, argumentation, research skills, and citation practices.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Margaret Liu", InstructorBio = "Dr. Liu is a published author and writing coach with expertise in academic and creative composition. She directs the university writing center.", DepartmentId = 3, IsFeatured = true },
            new() { Id = 9, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period through the 21st century.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright is a Fulbright scholar whose research centers on 20th-century American fiction and the literature of social movements.", DepartmentId = 3 },

            // Physics
            new() { Id = 10, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", InstructorName = "Dr. Nikolai Petrov", InstructorBio = "Dr. Petrov is an experimental physicist who previously worked at CERN. He brings particle physics expertise and a passion for hands-on learning to undergraduate education.", DepartmentId = 4 },
            new() { Id = 11, CourseCode = "PHYS 220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Prerequisite: PHYS 101.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM + Fri Lab 2:00–4:00 PM", InstructorName = "Dr. Nikolai Petrov", InstructorBio = "Dr. Petrov is an experimental physicist who previously worked at CERN. He brings particle physics expertise and a passion for hands-on learning to undergraduate education.", DepartmentId = 4 },

            // History
            new() { Id = 12, CourseCode = "HIST 101", Title = "World Civilizations I", Description = "Survey of world history from ancient civilizations through the Renaissance, including Mesopotamia, Egypt, Greece, Rome, China, and the Islamic Golden Age.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Dr. Amara Johnson", InstructorBio = "Dr. Johnson is a historian specializing in cross-cultural exchange in the ancient world. She has led archaeological expeditions in the Mediterranean.", DepartmentId = 5, IsFeatured = true },
            new() { Id = 13, CourseCode = "HIST 305", Title = "Modern European History", Description = "Europe from the Enlightenment through the Cold War: revolutions, industrialization, world wars, and the formation of the European Union.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Amara Johnson", InstructorBio = "Dr. Johnson is a historian specializing in cross-cultural exchange in the ancient world. She has led archaeological expeditions in the Mediterranean.", DepartmentId = 5 },
        ];
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public string GetDepartmentName(int departmentId) =>
        _departments.Find(d => d.Id == departmentId)?.Name ?? "Unknown";
}

